/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: LibraryContentType, ActivitySource, LibrarySort, ActivityEntry, LibraryListOptions
 *   Classes: UserLibrary
 *   Functions: isLibraryContentType, normalizeLibraryContentId
 * Internal
 *   Types: LibraryCursor
 *   Constants: savesCollection, activityCollection, maximumRecentItems, maximumLibraryPageSize
 * @end-catalog */

import { findPublicAudioTracks, findPublicAudioAccessRecords, publicAudioAccessPipeline, readyPublicAlbumFilter, readyPublicArtistFilter, findPublicAudioTrackById } from '../services/catalog/catalogVisibilityService';
import { touchReadyAlbumReferences } from '../services/catalog/albumReferenceFenceService';
import { ClientSession, ObjectId } from 'mongodb';
import { getDb } from '../infrastructure/database';
import { normalizeAudioTrackText } from './audioTrack';
import { withDerivedCoverArtUrl, withDisplayCoverArtUrl } from '../utils/coverArt';
import { resolvePublicCatalogBylines } from '../services/catalog/publicCatalogService';
import { composePlainNameByline } from '../services/catalog/catalogByline';
import { withReadyCatalogItemReferences } from '../services/catalog/catalogItemReferenceFenceService';
import { touchActiveAccount, withActiveAccount } from '../services/account/accountReferenceFenceService';
import { escapeRegex } from '../utils/search';
// Listener and content reads exclude a catalog-owned administrator field.
import { withoutExpectedTracklistProjection } from '../services/catalog/albumExpectedTracklist';

export type LibraryContentType = 'album' | 'audioTrack';
export type ActivitySource = 'recentlySaved' | 'recentlyPlayed';
export type LibrarySort = 'recentActivity' | 'recentlySaved' | 'recentlyPlayed';

export interface ActivityEntry {
    contentType: LibraryContentType;
    contentId: string;
    occurredAt: Date;
}

const savesCollection = 'userSaves';
const activityCollection = 'userActivity';
const maximumRecentItems = 20;
const maximumLibraryPageSize = 100;

interface LibraryCursor {
    sortAt: string | null;
    id: string;
}

export interface LibraryListOptions {
    query?: string;
    contentTypes?: LibraryContentType[];
    sort?: LibrarySort;
    limit?: number;
    cursor?: string;
}

export const isLibraryContentType = (value: string): value is LibraryContentType =>
    value === 'album' || value === 'audioTrack';

export const normalizeLibraryContentId = (value: string) => {
    try {
        return ObjectId.createFromHexString(String(value).trim()).toHexString();
    } catch {
        return null;
    }
};

export class UserLibrary {
    /** Reads ordinary access in the same transaction used to fence a new personal reference. */
    private static async publicContent(contentType: LibraryContentType, contentId: string, session?: ClientSession) {
        const normalized = normalizeLibraryContentId(contentId);
        if (!normalized) return null;
        if (contentType === 'audioTrack') return findPublicAudioTrackById(normalized, session);
        return getDb()!.collection('albums').findOne({
            _id: new ObjectId(normalized), ...readyPublicAlbumFilter
        }, { projection: { _id: 1 }, maxTimeMS: 3_000, ...(session ? { session } : {}) });
    }

    static async contentExists(contentType: LibraryContentType, contentId: string) {
        return Boolean(await this.publicContent(contentType, contentId));
    }

    /** The Track touch fences its own visibility; touching its Album also fences inherited access changes. */
    private static async requirePublicReference(contentType: LibraryContentType, contentId: string, session: ClientSession) {
        const content = await this.publicContent(contentType, contentId, session);
        if (!content) throw Object.assign(new Error('Content was not found.'), { statusCode: 404 });
        if (contentType === 'audioTrack' && content.albumId) {
            await touchReadyAlbumReferences([content.albumId], session);
        }
    }

    /**
     * Saves one item. A new save inherits the item's play time from Recently Played, so a
     * play that happened before the save still orders the Library like the history does.
     */
    static async save(userId: string, contentType: LibraryContentType, contentId: string) {
        const now = new Date();
        await withReadyCatalogItemReferences(
            [{ contentType, contentId }],
            async (session, [reference]) => {
                await touchActiveAccount(userId, session);
                const normalizedContentId = String(reference.contentId);
                await this.requirePublicReference(contentType, normalizedContentId, session);
                // Read inside the account-fenced transaction so a racing clear or play
                // serializes with this seed instead of reintroducing a cleared play time.
                const lastPlayedAt = await this.recentlyPlayedAt(
                    userId, contentType, normalizedContentId, session
                );
                await getDb()!.collection(savesCollection).updateOne(
                    { userId, contentType, contentId: normalizedContentId },
                    {
                        $setOnInsert: {
                            userId,
                            contentType,
                            contentId: normalizedContentId,
                            savedAt: now,
                            ...(lastPlayedAt ? { lastPlayedAt } : {}),
                            lastActivityAt: lastPlayedAt && lastPlayedAt > now ? lastPlayedAt : now
                        }
                    },
                    { upsert: true, session }
                );
                await this.recordActivity(userId, 'recentlySaved', [{
                    contentType,
                    contentId: normalizedContentId,
                    occurredAt: now
                }], session);
            }
        );
    }

    /** Removes the save and its activity together, serialized with saves and account deletion. */
    static async unsave(userId: string, contentType: LibraryContentType, contentId: string) {
        await withActiveAccount(userId, async (session) => {
            await getDb()!.collection(savesCollection).deleteOne(
                { userId, contentType, contentId }, { session }
            );
            await getDb()!.collection(activityCollection).updateOne(
                { userId },
                { $pull: { recentlySaved: { contentType, contentId } } } as any,
                { session }
            );
        });
    }

    /**
     * Empties Recently Played and drops the Library play times derived from those plays in
     * one transaction, so cleared plays stop ordering the Library. Saves, Save times, and
     * Recently Saved are unchanged.
     */
    static async clearRecentlyPlayed(userId: string) {
        await withActiveAccount(userId, async (session) => {
            await getDb()!.collection(activityCollection).updateOne(
                { userId },
                { $set: { recentlyPlayed: [], updatedAt: new Date() } },
                { session }
            );
            // Downloads are device-local, so without plays the save is the item's newest
            // server event. Unplayed saves already hold lastActivityAt === savedAt.
            await getDb()!.collection(savesCollection).updateMany(
                { userId, lastPlayedAt: { $exists: true } },
                [{ $set: { lastActivityAt: '$savedAt' } }, { $unset: 'lastPlayedAt' }],
                { session }
            );
        });
    }

    static async statuses(userId: string, items: Array<{ contentType: LibraryContentType; contentId: string }>) {
        if (items.length === 0) return [];
        const saved = await getDb()!
            .collection(savesCollection)
            .find({ userId, $or: items })
            .project({ contentType: 1, contentId: 1 })
            .limit(100)
            .toArray();
        const keys = new Set(saved.map((item) => `${item.contentType}:${item.contentId}`));
        return items.map((item) => ({
            ...item,
            saved: keys.has(`${item.contentType}:${item.contentId}`)
        }));
    }

    static async recordPlayed(userId: string, contentType: LibraryContentType, contentId: string) {
        const now = new Date();
        await withReadyCatalogItemReferences(
            [{ contentType, contentId }],
            async (session, [reference]) => {
                await touchActiveAccount(userId, session);
                const normalizedContentId = String(reference.contentId);
                await this.requirePublicReference(contentType, normalizedContentId, session);
                // Only saved items belong to the server Library. Recent playback history
                // still records unsaved items through the existing bounded activity list,
                // which save() reads to seed the play time if the item is saved later.
                await getDb()!.collection(savesCollection).updateOne(
                    { userId, contentType, contentId: normalizedContentId },
                    { $set: { lastPlayedAt: now, lastActivityAt: now } },
                    { session }
                );
                await this.recordActivity(userId, 'recentlyPlayed', [{
                    contentType,
                    contentId: normalizedContentId,
                    occurredAt: now
                }], session);
            }
        );
    }

    static async list(userId: string, options: LibraryListOptions = {}) {
        const sort = options.sort ?? 'recentActivity';
        const limit = Math.max(1, Math.min(options.limit ?? 50, maximumLibraryPageSize));
        const cursor = this.decodeLibraryCursor(options.cursor);
        const contentTypes = [...new Set(options.contentTypes ?? [])]
            .filter(isLibraryContentType);
        const match: Record<string, unknown> = { userId };
        if (contentTypes.length > 0) match.contentType = { $in: contentTypes };

        const sortExpression = sort === 'recentlySaved'
            ? '$savedAt'
            : sort === 'recentlyPlayed'
                ? '$lastPlayedAt'
                : { $ifNull: ['$lastActivityAt', '$savedAt'] };
        const pipeline: Record<string, unknown>[] = [
            { $match: match },
            { $addFields: { librarySortAt: sortExpression } }
        ];
        // Apply ordinary access before both title matching and pagination. Membership remains persisted.
        const query = options.query?.trim().slice(0, 100);
        pipeline.push(
            { $addFields: { searchContentId: { $convert: {
                input: '$contentId', to: 'objectId', onError: null, onNull: null
            } } } },
            ...(['album', 'audioTrack'] as const).map((type) => ({ $lookup: {
                from: type === 'album' ? 'albums' : 'audioTracks',
                let: { id: '$searchContentId', type: '$contentType' },
                pipeline: [
                    { $match: { $expr: { $and: [
                        { $eq: ['$_id', '$$id'] }, { $eq: ['$$type', type] }
                    ] } } },
                    ...(type === 'audioTrack' ? publicAudioAccessPipeline() : [{ $match: readyPublicAlbumFilter }]),
                    ...(query ? [{ $match: { title: { $regex: escapeRegex(query), $options: 'i' } } }] : []),
                    { $project: { _id: 1 } }
                ],
                as: type === 'album' ? 'matchingAlbum' : 'matchingTrack'
            } })),
            { $match: { $or: [
                { 'matchingAlbum.0': { $exists: true } },
                { 'matchingTrack.0': { $exists: true } }
            ] } }
        );
        if (cursor) {
            const cursorId = ObjectId.createFromHexString(cursor.id);
            pipeline.push(cursor.sortAt
                ? {
                    $match: {
                        $or: [
                            { librarySortAt: { $lt: new Date(cursor.sortAt) } },
                            {
                                librarySortAt: new Date(cursor.sortAt),
                                _id: { $lt: cursorId }
                            },
                            { librarySortAt: null }
                        ]
                    }
                }
                : {
                    $match: {
                        librarySortAt: null,
                        _id: { $lt: cursorId }
                    }
                });
        }
        pipeline.push(
            { $sort: { librarySortAt: -1, _id: -1 } },
            { $limit: limit + 1 }
        );

        const saves: any[] = await getDb()!
            .collection(savesCollection)
            .aggregate(pipeline, { maxTimeMS: 3_000 })
            .toArray();
        const page = saves.slice(0, limit);
        const albumIds = page
            .filter((item) => item.contentType === 'album')
            .map((item) => ObjectId.createFromHexString(item.contentId));
        const trackIds = page
            .filter((item) => item.contentType === 'audioTrack')
            .map((item) => ObjectId.createFromHexString(item.contentId));
        const db = getDb()!;
        const [albums, tracks] = await Promise.all([
            albumIds.length > 0
                ? db.collection('albums').find({
                    _id: { $in: albumIds },
                    ...readyPublicAlbumFilter
                }).project(withoutExpectedTracklistProjection).maxTimeMS(3_000).toArray()
                : [],
            trackIds.length > 0
                ? findPublicAudioAccessRecords({
                    // Existing saves remain visible when their audio becomes
                    // unavailable; the listener projection disables playback.
                    _id: { $in: trackIds }
                }).maxTimeMS(3_000).toArray()
                : []
        ]);
        const readyTracks = trackIds.length > 0
            ? await findPublicAudioTracks({ _id: { $in: trackIds } }).project({ _id: 1 }).toArray()
            : [];
        const playableTrackIds = new Set(readyTracks.map(track => String(track._id)));
        const linkedAlbumIds = tracks
            .map((track: any) => String(track.albumId ?? ''))
            .filter((id) => ObjectId.isValid(id));
        const linkedAlbums = linkedAlbumIds.length > 0
            ? await db.collection('albums').find({
                _id: { $in: linkedAlbumIds.map((id) => ObjectId.createFromHexString(id)) },
                ...readyPublicAlbumFilter
            }).project(withoutExpectedTracklistProjection).maxTimeMS(3_000).toArray()
            : [];
        const trackArtistIds = tracks.flatMap((track: any) =>
            (Array.isArray(track.artistIds) ? track.artistIds : [])
                .map(String)
                .filter((id: string) => ObjectId.isValid(id))
        );
        const artistQueries: Record<string, unknown>[] = [];
        if (trackArtistIds.length > 0) {
            artistQueries.push({
                _id: { $in: trackArtistIds.map((id) => ObjectId.createFromHexString(id)) }
            });
        }
        if (albumIds.length > 0) {
            artistQueries.push({ albumIds: { $in: albumIds.map(String) } });
        }
        const artists = artistQueries.length > 0
            ? await db.collection('artists')
                .find({ $and: [readyPublicArtistFilter, { $or: artistQueries }] })
                .maxTimeMS(3_000)
                .toArray()
            : [];
        const creditBylines = await resolvePublicCatalogBylines([...albums, ...tracks]);
        const artistNamesById = new Map(
            artists.map((artist: any) => [String(artist._id), String(artist.name ?? '')])
        );
        const albumsById = new Map(
            [...albums, ...linkedAlbums].map((album: any) => [String(album._id), album])
        );
        const tracksById = new Map(tracks.map((track: any) => [String(track._id), track]));
        const items = page.map((save): any | null => {
            const common = {
                contentType: save.contentType as LibraryContentType,
                contentId: String(save.contentId),
                savedAt: save.savedAt,
                lastPlayedAt: save.lastPlayedAt ?? null,
                lastActivityAt: save.lastActivityAt ?? save.savedAt
            };
            if (save.contentType === 'album') {
                const album = albumsById.get(String(save.contentId));
                // Unmigrated owners and the Credit-reads rollback share the byline cap.
                const legacyCreator = composePlainNameByline(artists
                    .filter((artist: any) =>
                        (Array.isArray(artist.albumIds) ? artist.albumIds : [])
                            .map(String)
                            .includes(String(save.contentId))
                    )
                    .map((artist: any) => String(artist.name ?? '').trim()));
                return album ? {
                    ...common,
                    creator: creditBylines.get(String(album._id)) || legacyCreator || null,
                    album: withDerivedCoverArtUrl(album)
                } : null;
            }
            const track = tracksById.get(String(save.contentId));
            if (!track) return null;
            const legacyCreator = composePlainNameByline((Array.isArray(track.artistIds) ? track.artistIds : [])
                .map((id: unknown) => artistNamesById.get(String(id))?.trim() ?? ''));
            const linkedAlbum = albumsById.get(String(track.albumId ?? ''));
            return {
                ...common,
                creator: creditBylines.get(String(track._id)) || legacyCreator || null,
                audioTrack: withDisplayCoverArtUrl(
                    {
                        ...normalizeAudioTrackText(track),
                        catalogAvailable: playableTrackIds.has(String(track._id)),
                        albumId: linkedAlbum ? track.albumId : null
                    },
                    linkedAlbum
                )
            };
        }).filter((item): item is any => item !== null);
        const last = page[page.length - 1];
        return {
            items,
            nextCursor: saves.length > limit && last
                ? this.encodeLibraryCursor({
                    sortAt: last.librarySortAt instanceof Date
                        ? last.librarySortAt.toISOString()
                        : null,
                    id: String(last._id)
                })
                : null
        };
    }

    static async recent(userId: string, source: ActivitySource, limit: number = maximumRecentItems) {
        const document: any = await getDb()!
            .collection(activityCollection)
            .find({ userId })
            .project({ [source]: 1 })
            .next();
        const entries: ActivityEntry[] = Array.isArray(document?.[source]) ? document[source] : [];
        return entries.slice(-Math.max(1, Math.min(limit, maximumRecentItems))).reverse();
    }

    static async cleanupContent(contentType: LibraryContentType, contentId: string) {
        const db = getDb()!;
        const contentIds: Array<string | ObjectId> = [];
        if (/^[0-9a-fA-F]{24}$/.test(contentId)) {
            const objectId = ObjectId.createFromHexString(contentId);
            const canonicalContentId = objectId.toHexString();
            contentIds.push(canonicalContentId, canonicalContentId.toUpperCase(), objectId);
            if (contentId !== canonicalContentId) contentIds.push(contentId);
        } else {
            contentIds.push(contentId);
        }
        await Promise.all([
            db.collection(savesCollection).deleteMany({
                contentType,
                contentId: { $in: contentIds }
            }),
            db.collection(activityCollection).updateMany(
                {},
                {
                    $pull: {
                        recentlySaved: { contentType, contentId: { $in: contentIds } },
                        recentlyPlayed: { contentType, contentId: { $in: contentIds } }
                    }
                } as any
            )
        ]);
    }

    /** Removes listener-owned saves and activity during account deletion. */
    static async deleteForUser(userId: string) {
        await Promise.all([
            getDb()!.collection(savesCollection).deleteMany({ userId }),
            getDb()!.collection(activityCollection).deleteMany({ userId })
        ]);
    }

    /** Returns when one item was last played while it is still in the bounded Recently Played history. */
    private static async recentlyPlayedAt(
        userId: string,
        contentType: LibraryContentType,
        contentId: string,
        session: ClientSession
    ): Promise<Date | null> {
        const activity = await getDb()!.collection(activityCollection).findOne(
            { userId },
            {
                projection: { _id: 0, recentlyPlayed: { $elemMatch: { contentType, contentId } } },
                session
            }
        );
        const occurredAt = activity?.recentlyPlayed?.[0]?.occurredAt;
        return occurredAt instanceof Date && !Number.isNaN(occurredAt.getTime()) ? occurredAt : null;
    }

    private static async recordActivity(
        userId: string,
        source: ActivitySource,
        entries: ActivityEntry[],
        session?: ClientSession
    ) {
        const keys = entries.map((entry) => `${entry.contentType}:${entry.contentId}`);
        await getDb()!.collection(activityCollection).updateOne(
            { userId },
            [{
                $set: {
                    userId,
                    [source]: {
                        $slice: [{
                            $concatArrays: [{
                                $filter: {
                                    input: { $ifNull: [`$${source}`, []] },
                                    as: 'entry',
                                    cond: {
                                        $not: [{
                                            $in: [
                                                { $concat: ['$$entry.contentType', ':', '$$entry.contentId'] },
                                                keys
                                            ]
                                        }]
                                    }
                                }
                            }, entries]
                        }, -maximumRecentItems]
                    },
                    updatedAt: new Date()
                }
            }],
            { upsert: true, ...(session ? { session } : {}) }
        );
    }

    private static encodeLibraryCursor(cursor: LibraryCursor) {
        return Buffer.from(JSON.stringify(cursor), 'utf8').toString('base64url');
    }

    private static decodeLibraryCursor(value?: string): LibraryCursor | null {
        if (!value) return null;
        try {
            const parsed = JSON.parse(Buffer.from(value, 'base64url').toString('utf8'));
            const id = String(parsed?.id ?? '');
            const sortAt = parsed?.sortAt === null ? null : String(parsed?.sortAt ?? '');
            if (!ObjectId.isValid(id) || (sortAt !== null && Number.isNaN(Date.parse(sortAt)))) {
                return null;
            }
            return { id, sortAt };
        } catch {
            return null;
        }
    }
}
